package com.srenterprises.repository; import com.srenterprises.entity.*; import org.springframework.data.jpa.repository.*; import jakarta.persistence.*; import java.util.*; public interface InventoryRepository extends JpaRepository<Inventory,UUID>{Optional<Inventory> findByProductId(UUID id); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select i from Inventory i where i.product.id=:id") Optional<Inventory> lockByProductId(UUID id);}
